import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.Statement;

public class DatabaseExample {
    public static void main(String[] args) {
        String url = "jdbc:mysql://localhost:3306/mydb";
        String user = "root";
        String password = "password";

        try {
            // Vulnerable: Directly using the user and password in the connection string
            Connection conn = DriverManager.getConnection(url, user, password);
            Statement stmt = conn.createStatement();
            stmt.executeUpdate("INSERT INTO users (username, password) VALUES ('admin', 'password')");
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
```

In the first snippet, the user and password are directly included in the connection string, which is a **vulnerable** practice as it exposes sensitive information. In the second snippet, the user and password are passed as parameters to the `DriverManager.getConnection` method, which is a more secure way to handle sensitive information.

